import json
def f(g):
    w=len(g[0]); m={'L':2,'M':4,'R':3}
    d={i: m['L'] if i<w/3 else (m['M'] if i<2*w/3 else m['R']) for i in range(w)}
    return [[d[j] for j in range(w)] for r in g if any(c!=0 for c in r)]
